class Solution {
    private int[] memo = new int[10001];
    public int racecar(int target) {
        return dp(target);
    }
    private int dp(int t) {
        if (t == 0) return 0;
        if (memo[t] > 0) return memo[t];
        int k = 32 - Integer.numberOfLeadingZeros(t);
        if ((1 << k) - 1 == t) return memo[t] = k;
        int ans = k + 1 + dp((1 << k) - 1 - t);
        for (int j = 0; j < k - 1; j++) {
            ans = Math.min(ans, (k - 1) + 1 + j + 1 + dp(t - ((1 << (k - 1)) - 1) + ((1 << j) - 1)));
        }
        return memo[t] = ans;
    }
}

var racecar = function(target) {
    const memo = new Map();
    memo.set(0, 0);
    function dp(t) {
        if (memo.has(t)) return memo.get(t);
        const k = 32 - Math.clz32(t);
        if ((1 << k) - 1 === t) {
            memo.set(t, k);
            return k;
        }
        let ans = k + 1 + dp((1 << k) - 1 - t);
        for (let j = 0; j < k - 1; j++) {
            ans = Math.min(ans, (k - 1) + 1 + j + 1 + dp(t - ((1 << (k - 1)) - 1) + ((1 << j) - 1)));
        }
        memo.set(t, ans);
        return ans;
    }
    return dp(target);
};
